(function(E){ const x = E["exam-07"] = E["exam-07"] || {units:{}}; (x.units = x.units || {})["x07-w2"] = {"id":"x07-w2","patterns":["W2-advdis","W2T-environment","TR-halfquestion"],"title":{"en":"Writing Task 2","tr":"Writing Task 2","fa":"Writing Task 2 (نوشتن، تکلیف ۲)"},"objective":{"en":"In this lesson you will learn to plan and write an essay of at least 250 words that weighs the advantages and disadvantages of a trend and says clearly which are greater.","tr":"Bu derste bir eğilimin avantajlarını ve dezavantajlarını tartan ve hangisinin daha büyük olduğunu açıkça söyleyen en az 250 kelimelik bir yazı planlayıp yazmayı öğreneceksin.","fa":"در این درس یاد می‌گیری مقاله‌ای دست‌کم ۲۵۰ کلمه‌ای را برنامه‌ریزی کنی و بنویسی که مزایا و معایب یک روند را می‌سنجد و روشن می‌گوید کدام بیشتر است."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 2: advantages and disadvantages","tr":"Writing Task 2: avantajlar ve dezavantajlar","fa":"Writing Task 2: مزایا و معایب"},"objective":{"en":"In this lesson you will learn to plan and write an essay of at least 250 words that weighs the advantages and disadvantages of a trend and says clearly which are greater.","tr":"Bu derste bir eğilimin avantajlarını ve dezavantajlarını tartan ve hangisinin daha büyük olduğunu açıkça söyleyen en az 250 kelimelik bir yazı planlayıp yazmayı öğreneceksin.","fa":"در این درس یاد می‌گیری مقاله‌ای دست‌کم ۲۵۰ کلمه‌ای را برنامه‌ریزی کنی و بنویسی که مزایا و معایب یک روند را می‌سنجد و روشن می‌گوید کدام بیشتر است."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"250+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"40 min","tr":"40 dk","fa":"۴۰ دقیقه"}},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"4"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: cheap air travel","tr":"Bu sınav: ucuz hava yolculuğu","fa":"این آزمون: سفر هوایی ارزان"},"intro":{"en":"Advantages-and-disadvantages questions are among the most common Task 2 forms. The environment and transport are a regular theme. The key word is \"outweigh\": the reader needs your judgement, not only a list.","tr":"Avantaj-dezavantaj soruları en sık çıkan Task 2 türlerindendir. Çevre ve ulaşım düzenli bir temadır. Anahtar kelime \"outweigh\": okur yalnızca bir liste değil, senin yargını bekler.","fa":"سؤال‌های مزایا و معایب از رایج‌ترین شکل‌های Task 2 هستند. محیط زیست و حمل‌ونقل موضوعی همیشگی است. کلمه‌ی کلیدی «outweigh» است: خواننده داوری تو را می‌خواهد، نه فقط یک فهرست."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-w2-ctx","exam":true,"patterns":["W2-advdis","W2T-environment"],"often":{"pattern":"W2-advdis","n":14,"of":76,"label":{"en":"Comes up often in the real exam: 14 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}},"title":{"en":"Advantages and disadvantages: cheap flights","tr":"Avantajlar ve dezavantajlar: ucuz uçuşlar","fa":"مزایا و معایب: پرواز ارزان"},"asks":{"en":"The question describes a trend, flying has become cheap and common, and asks whether its advantages outweigh its disadvantages. You must discuss both sides and give a clear final judgement.","tr":"Soru bir eğilimi anlatıyor, uçmak ucuzladı ve yaygınlaştı, ve avantajlarının dezavantajlarından ağır basıp basmadığını soruyor. İki tarafı da tartışmalı ve net bir sonuç kararı vermelisin.","fa":"سؤال روندی را توصیف می‌کند، اینکه پرواز ارزان و همه‌گیر شده، و می‌پرسد آیا مزایایش بر معایبش می‌چربد یا نه. باید هر دو طرف را بررسی کنی و یک داوری نهایی روشن بدهی."},"fields":["The trend in your words","Advantages","Disadvantages","Your judgement","Conclusion"],"words":[{"a":"cheap flights","b":"low-cost air travel / budget airlines","tr":"ucuz uçuşlar","fa":"پروازهای ارزان"},{"a":"outweigh","b":"are greater or more important than","tr":"ağır basmak","fa":"سنگین‌تر بودن، چربیدن"},{"a":"emissions","b":"the gases released by planes","tr":"emisyonlar, salımlar","fa":"گازهای منتشرشده"},{"a":"climate change","b":"global warming","tr":"iklim değişikliği","fa":"تغییر اقلیم"},{"a":"broaden horizons","b":"learn about other cultures","tr":"ufkunu genişletmek","fa":"افق دید را گسترده کردن"},{"a":"tourism income","b":"money from visitors","tr":"turizm geliri","fa":"درآمد گردشگری"},{"a":"short-haul","b":"short flights, for example within one continent","tr":"kısa mesafeli","fa":"کوتاه‌برد"},{"a":"alternative","b":"another way, such as the train","tr":"alternatif","fa":"جایگزین"},{"a":"frequent flyers","b":"people who fly many times a year","tr":"sık uçanlar","fa":"کسانی که زیاد پرواز می‌کنند"},{"a":"a tax on","b":"an extra charge on","tr":"... üzerine vergi","fa":"مالیات بر"},{"a":"on balance","b":"taking everything into account","tr":"her şey göz önüne alındığında","fa":"با در نظر گرفتن همه‌چیز"},{"a":"in my view","b":"I believe / I would argue","tr":"bence","fa":"به نظر من"}],"traps":[{"en":"Listing advantages and disadvantages without saying which are more important. \"Outweigh\" needs a judgement.","tr":"Hangisinin daha önemli olduğunu söylemeden avantajları ve dezavantajları sıralamak. \"Outweigh\" bir yargı ister.","fa":"فهرست کردن مزایا و معایب بدون گفتن اینکه کدام مهم‌تر است. «outweigh» داوری می‌خواهد."},{"en":"Writing only about the environment. The question asks about cheap air travel as a whole, so both sides need real examples.","tr":"Yalnızca çevre hakkında yazmak. Soru ucuz hava yolculuğunu bütün olarak soruyor; iki tarafın da gerçek örneklere ihtiyacı var.","fa":"نوشتن فقط درباره‌ی محیط زیست. سؤال درباره‌ی کل سفر هوایی ارزان است، پس هر دو طرف مثال واقعی لازم دارند."}],"example":{"text":"Question: \"...Do the advantages of online shopping outweigh the disadvantages?\"","item":"Which sentence gives a judgement?","answer":"Although online shopping has hurt some local shops, I believe its convenience for most people outweighs this cost.","why":{"en":"It names one disadvantage, one advantage, and says which is greater.","tr":"Bir dezavantaj, bir avantaj söylüyor ve hangisinin daha büyük olduğunu belirtiyor.","fa":"یک عیب و یک مزیت را می‌گوید و مشخص می‌کند کدام بزرگ‌تر است."}}},{"id":"W2T-environment","ctx":["W2-problem","W2-twopart","W2T-environment"],"title":{"en":"Environment, resources and transport","tr":"Çevre, kaynaklar ve ulaşım","fa":"محیط زیست، منابع و حمل‌ونقل"},"asks":{"en":"Questions about the planet and its resources: free clean water, air travel, the loss of plant and animal species, food security, spending on transport, plastic.","tr":"Gezegen ve kaynakları üzerine sorular: ücretsiz temiz su, hava yolculuğu, bitki ve hayvan türlerinin kaybı, gıda güvenliği, ulaşım harcamaları, plastik.","fa":"سؤال‌هایی درباره‌ی زمین و منابعش: آب سالم رایگان، سفر هوایی، از بین رفتن گونه‌های گیاهی و جانوری، امنیت غذایی، هزینه برای حمل‌ونقل، پلاستیک."},"fields":["Plastic pollution: what are the causes, and how can it be reduced?","Should clean water be free for every home?","Fewer species of plants and animals: why, and what can be done?","Should governments spend more on public transport than on roads?","Air travel: should it be limited?"],"words":[{"a":"pollution","b":"contamination / emissions","tr":"kirlilik","fa":"آلودگی"},{"a":"rubbish","b":"waste / litter","tr":"atık, çöp","fa":"زباله"},{"a":"plastic bags","b":"single-use plastic","tr":"tek kullanımlık plastik","fa":"پلاستیک یک‌بارمصرف"},{"a":"animals and plants","b":"wildlife / biodiversity","tr":"biyolojik çeşitlilik","fa":"تنوع زیستی"},{"a":"disappear","b":"become extinct / die out","tr":"yok olmak","fa":"منقرض شدن"},{"a":"climate","b":"global warming / climate change","tr":"iklim değişikliği","fa":"تغییرات اقلیمی"},{"a":"use less","b":"reduce consumption","tr":"tüketimi azaltmak","fa":"مصرف را کم کردن"},{"a":"use again","b":"reuse / recycle","tr":"yeniden kullanmak","fa":"دوباره استفاده کردن"},{"a":"clean energy","b":"renewable energy","tr":"yenilenebilir enerji","fa":"انرژی تجدیدپذیر"},{"a":"flying","b":"air travel / aviation","tr":"hava yolculuğu","fa":"سفر هوایی"},{"a":"government rules","b":"regulations / legislation","tr":"düzenlemeler","fa":"مقررات"},{"a":"everyone must help","b":"individual and collective responsibility","tr":"bireysel ve toplu sorumluluk","fa":"مسئولیت فردی و جمعی"}],"traps":[{"en":"Do not write only \"governments should do something\". Say who, what and how.","tr":"Yalnızca \"hükümetler bir şey yapmalı\" yazma. Kimin, neyi ve nasıl yapacağını söyle.","fa":"فقط ننویس «دولت‌ها باید کاری بکنند». بگو چه کسی، چه کاری و چطور."},{"en":"Environment essays easily turn into lists. Develop two or three ideas fully instead of listing six.","tr":"Çevre kompozisyonları kolayca listeye döner. Altı fikri sıralamak yerine iki üç fikri tam olarak geliştir.","fa":"مقاله‌های محیط زیستی راحت به فهرست تبدیل می‌شوند. به‌جای شمردن شش ایده، دو سه ایده را کامل باز کن."}],"example":{"text":"Question: Some people think that every home should receive clean water free of charge. To what extent do you agree or disagree?","item":"Write a thesis sentence.","answer":"I agree that every home should receive a basic amount of clean water free of charge, but people who use more than this should pay, so that water is not wasted.","why":{"en":"A clear position, refined with a condition that answers the obvious objection.","tr":"Net bir tutum; akla gelen itiraza cevap veren bir koşulla inceltilmiş.","fa":"یک موضع روشن که با شرطی دقیق‌تر شده و به اعتراض آشکار جواب می‌دهد."}},"ideas":["+ A small charge on plastic bags quickly reduces their use.","- Individual action is not enough without rules for companies.","+ Free basic water is a human right and protects health.","- Free water can encourage waste unless use above a basic amount is paid for.","+ Protected areas allow species to recover.","- Farming and building need land, so protection creates conflict."],"general":true,"patterns":["W2-problem","W2-twopart","W2T-environment"],"often":{"pattern":"W2T-environment","n":6,"of":76,"label":{"en":"Comes up often in the real exam: 6 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Both sides, then a verdict","tr":"İki taraf, sonra bir karar","fa":"هر دو طرف، بعد یک حکم"},"body":{"en":"Write at least 250 words in about 40 minutes. The introduction states the trend in your words and your judgement; one body paragraph covers the advantages, one the disadvantages; the conclusion repeats which side is greater and why.","tr":"Yaklaşık 40 dakikada en az 250 kelime yaz. Giriş eğilimi kendi kelimelerinle ve yargını verir; bir gövde paragrafı avantajları, biri dezavantajları ele alır; sonuç hangi tarafın daha ağır bastığını ve nedenini tekrarlar.","fa":"در حدود ۴۰ دقیقه دست‌کم ۲۵۰ کلمه بنویس. مقدمه روند را با کلمه‌های خودت و داوری‌ات را می‌گوید؛ یک پاراگراف بدنه مزایا را پوشش می‌دهد و یکی معایب را؛ نتیجه تکرار می‌کند کدام طرف سنگین‌تر است و چرا."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Weigh before you write","tr":"Yazmadan önce tart","fa":"قبل از نوشتن بسنج"},"steps":[{"en":"List two advantages and two disadvantages, each with an example.","tr":"İki avantaj ve iki dezavantajı, her biri örnekli olarak listele.","fa":"دو مزیت و دو عیب را، هر کدام با یک مثال، فهرست کن."},{"en":"Decide which side is more important, and why: that is your judgement.","tr":"Hangi tarafın daha önemli olduğuna ve nedenine karar ver: bu senin yargın.","fa":"تصمیم بگیر کدام طرف مهم‌تر است و چرا: این داوری توست."},{"en":"Put the side you think is weaker first, and finish the body with the stronger side.","tr":"Daha zayıf bulduğun tarafı önce koy, gövdeyi daha güçlü tarafla bitir.","fa":"طرفی را که ضعیف‌تر می‌دانی اول بیاور و بدنه را با طرف قوی‌تر تمام کن."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Weighing the two sides","tr":"İki tarafı tartmak","fa":"سنجیدن دو طرف"},"table":{"headers":{"en":["Job","Phrase"],"tr":["İşlev","İfade"],"fa":["کارکرد","عبارت"]},"rows":[["give the judgement early","I believe the disadvantages outweigh the advantages."],["present an advantage","One clear benefit is that..."],["present a disadvantage","The most serious drawback, however, is..."],["compare their weight","This matters far more than..."],["conclude","On balance, ..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A comparison sentence, step by step","tr":"Bir karşılaştırma cümlesi, adım adım","fa":"یک جمله‌ی مقایسه، قدم به قدم"},"instruction":"Question: \"...Do the advantages of working from home outweigh the disadvantages?\"","item":"Write the sentence that weighs the two sides.","answer":"Although some employees feel lonely at home, I believe the time and money saved on travelling matter far more for most workers.","walk":[{"en":"Start with the weaker side, introduced by \"although\".","tr":"Daha zayıf tarafla, \"although\" ile başla.","fa":"با طرف ضعیف‌تر شروع کن، با «although»."},{"en":"Then give the stronger side with a concrete benefit: time and money.","tr":"Sonra güçlü tarafı somut bir faydayla ver: zaman ve para.","fa":"بعد طرف قوی‌تر را با یک فایده‌ی ملموس بگو: وقت و پول."},{"en":"\"Matter far more\" makes the judgement clear.","tr":"\"Matter far more\" yargıyı netleştiriyor.","fa":"«matter far more» داوری را روشن می‌کند."}]},"quick":{"prompt":"Question: \"Do the advantages outweigh the disadvantages?\" Which conclusion answers it?","options":["There are advantages and disadvantages.","On balance, the benefits are greater than the problems.","This is a complicated question."],"correct":1,"why":{"en":"Only the first says which side is greater; the others avoid the question.","tr":"Yalnızca ilki hangi tarafın büyük olduğunu söylüyor; diğerleri sorudan kaçıyor.","fa":"فقط اولی می‌گوید کدام طرف بزرگ‌تر است؛ بقیه از سؤال طفره می‌روند."}},"remember":{"en":"Discuss both sides with examples, and say clearly which is greater: that is what \"outweigh\" asks for.","tr":"İki tarafı örneklerle tartış ve hangisinin daha büyük olduğunu açıkça söyle: \"outweigh\" bunu ister.","fa":"هر دو طرف را با مثال بررسی کن و روشن بگو کدام بزرگ‌تر است: «outweigh» همین را می‌خواهد."},"type":"explain","id":"c-x07-w2-e","course":"ielts-exams","exam":"exam-07","unit":"x07-w2"},"writing":{"taskKind":"exam","title":{"en":"Write the essay: cheap air travel","tr":"Yazıyı yaz: ucuz hava yolculuğu","fa":"مقاله را بنویس: سفر هوایی ارزان"},"task":"task2","reviewLabel":{"en":"Exam 7 · Writing Task 2 (advantages and disadvantages: cheap air travel)"},"timed":40,"minWords":250,"ctx":["W2-advdis","W2T-environment"],"prompt":{"en":"You should spend about 40 minutes on this task. Write about the following topic: Air travel has become much cheaper in recent decades, and many people now fly several times a year. Do the advantages of cheap air travel outweigh the disadvantages? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","tr":"Bu göreve yaklaşık 40 dakika ayırmalısın. Şu konu hakkında yaz: Son on yıllarda hava yolculuğu çok ucuzladı ve birçok insan artık yılda birkaç kez uçuyor. Ucuz hava yolculuğunun avantajları dezavantajlarından ağır basıyor mu? Cevabını gerekçelendir ve kendi bilgi ya da deneyimlerinden ilgili örnekler ver. En az 250 kelime yaz.","fa":"باید حدود ۴۰ دقیقه برای این تکلیف وقت بگذاری. درباره‌ی این موضوع بنویس: سفر هوایی در دهه‌های اخیر خیلی ارزان‌تر شده و خیلی‌ها حالا سالی چند بار پرواز می‌کنند. آیا مزایای سفر هوایی ارزان بر معایبش می‌چربد؟ برای جوابت دلیل بیاور و از دانسته‌ها یا تجربه‌ی خودت مثال‌های مرتبط بزن. دست‌کم ۲۵۰ کلمه بنویس."},"model":"Over the last thirty years, the price of flying has fallen dramatically, and for many people a weekend in another country now costs less than a train ticket across their own. While cheap air travel has brought real benefits, I believe its disadvantages, particularly for the environment, now outweigh them.\n\nThere is no doubt that low-cost flights have advantages. Millions of people who could never have afforded to travel abroad can now visit other countries, meet people from different cultures and broaden their horizons. Cheap flights also support many economies. Regions that depend on tourism, such as islands in the Mediterranean, rely on a steady stream of visitors arriving by air, and thousands of local jobs are linked to them.\n\nHowever, these benefits come at a high price. Aircraft produce large amounts of greenhouse gases, and because flying is so cheap, many people now take several short trips a year that they would never have taken before. A single return flight across a continent can produce more emissions than some people in poorer countries are responsible for in a whole year. Furthermore, the popularity of short-haul flights has led to more noise and pollution around airports, and it has drawn passengers away from trains, which are a far cleaner alternative for journeys of a few hundred kilometres.\n\nIn my view, the damage to the climate matters more than the convenience of cheap holidays, because its effects will be felt by everyone for generations. This does not mean that flying should become a luxury again, but governments could tax frequent flyers more heavily and invest in fast rail links.\n\nIn conclusion, although cheap flights have opened the world to many people, their environmental cost is now too great to ignore.","moves":[{"label":{"en":"1 Introduction: the trend + your judgement","tr":"1 Giriş: eğilim + yargın","fa":"۱ مقدمه: روند + داوری تو"},"text":"While cheap air travel has brought real benefits, I believe its disadvantages... now outweigh them."},{"label":{"en":"2 Advantages, with examples","tr":"2 Avantajlar, örneklerle","fa":"۲ مزایا، با مثال"},"text":"There is no doubt that low-cost flights have advantages... islands in the Mediterranean..."},{"label":{"en":"3 Disadvantages, with examples","tr":"3 Dezavantajlar, örneklerle","fa":"۳ معایب، با مثال"},"text":"However, these benefits come at a high price... trains, which are a far cleaner alternative..."},{"label":{"en":"4 Weighing the two sides","tr":"4 İki tarafı tartmak","fa":"۴ سنجیدن دو طرف"},"text":"In my view, the damage to the climate matters more than the convenience of cheap holidays..."},{"label":{"en":"5 Conclusion: the same judgement","tr":"5 Sonuç: aynı yargı","fa":"۵ نتیجه: همان داوری"},"text":"In conclusion, although cheap flights have opened the world to many people..."}],"rubric":["Covers the task: every part of the question answered, one clear position, ideas explained and supported.","Organised: introduction, body paragraphs with one main idea each, conclusion; linking that sounds natural.","Words: topic words used precisely and naturally; the question paraphrased, not copied.","Sentences: a range of sentence types, mostly accurate; articles, agreement and punctuation checked."],"rubricI18n":{"tr":["Görevi karşılıyor: sorunun her kısmı cevaplanmış, tek ve net bir tutum, fikirler açıklanmış ve desteklenmiş.","Düzenli: giriş, her biri tek ana fikirli gövde paragrafları, sonuç; doğal görünen bağlantılar.","Kelimeler: konu kelimeleri yerinde ve doğal kullanılmış; soru kopyalanmamış, başka sözcüklerle anlatılmış.","Cümleler: çeşitli cümle türleri, çoğunlukla doğru; tanımlıklar, özne-yüklem uyumu ve noktalama kontrol edilmiş."],"fa":["تکلیف را پوشش می‌دهد: به همه‌ی بخش‌های سؤال جواب داده، یک موضع روشن دارد، ایده‌ها توضیح و پشتوانه دارند.","منظم است: مقدمه، پاراگراف‌هایی که هرکدام یک ایده‌ی اصلی دارند، نتیجه‌گیری؛ ربط‌دهنده‌هایی که طبیعی‌اند.","کلمه‌ها: کلمه‌های موضوعی دقیق و طبیعی به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده، نه کپی.","جمله‌ها: انواع مختلف جمله، بیشترشان درست؛ حرف تعریف، مطابقت فعل و فاعل و نشانه‌گذاری بررسی شده."]},"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The question is not really answered; no clear position.","tr":"Soru tam olarak cevaplanmamış; net bir tutum yok.","fa":"در واقع به سؤال جواب داده نشده؛ موضع روشنی نیست."},{"en":"A position, but only part of the question is answered, or ideas are not explained.","tr":"Bir tutum var ama sorunun yalnızca bir kısmı cevaplanmış ya da fikirler açıklanmamış.","fa":"موضعی هست، اما فقط بخشی از سؤال جواب داده شده یا ایده‌ها توضیح داده نشده‌اند."},{"en":"Every part answered, one clear position, main ideas supported.","tr":"Her kısım cevaplanmış, tek ve net bir tutum, ana fikirler desteklenmiş.","fa":"به همه‌ی بخش‌ها جواب داده شده، یک موضع روشن هست و ایده‌های اصلی پشتیبانی شده‌اند."},{"en":"A clear, consistent position; ideas fully explained with relevant examples.","tr":"Net ve tutarlı bir tutum; fikirler yerinde örneklerle tam açıklanmış.","fa":"موضعی روشن و یکدست؛ ایده‌ها با مثال‌های مرتبط کامل توضیح داده شده‌اند."}],"organised":[{"en":"No clear paragraphs.","tr":"Net paragraflar yok.","fa":"پاراگراف‌های روشنی ندارد."},{"en":"Paragraphs, but more than one main idea in each, or forced linking words.","tr":"Paragraflar var ama her birinde birden fazla ana fikir ya da zorlama bağlaçlar.","fa":"پاراگراف دارد، اما در هر کدام بیش از یک ایده‌ی اصلی هست یا کلمه‌های ربط تصنعی‌اند."},{"en":"Introduction, body paragraphs with one idea each, conclusion.","tr":"Giriş, her biri tek fikirli gövde paragrafları, sonuç.","fa":"مقدمه، پاراگراف‌هایی که هر کدام یک ایده دارند، نتیجه."},{"en":"A logical flow from start to end; linking is natural.","tr":"Baştan sona mantıklı bir akış; bağlantılar doğal.","fa":"جریانی منطقی از اول تا آخر؛ ربط‌ها طبیعی‌اند."}],"words":[{"en":"Very basic words; the question is copied.","tr":"Çok temel kelimeler; soru kopyalanmış.","fa":"کلمه‌های خیلی ساده؛ صورت سؤال کپی شده."},{"en":"Topic words repeated; some wrong word choices.","tr":"Konu kelimeleri tekrarlanmış; bazı yanlış kelime seçimleri.","fa":"کلمه‌های موضوع تکرار شده‌اند؛ چند انتخاب کلمه‌ی غلط هست."},{"en":"Topic words used well; the question is said in other words.","tr":"Konu kelimeleri iyi kullanılmış; soru başka sözcüklerle anlatılmış.","fa":"کلمه‌های موضوع خوب به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده."},{"en":"Precise, natural topic words; almost no errors.","tr":"Yerinde, doğal konu kelimeleri; neredeyse hatasız.","fa":"کلمه‌های موضوعِ دقیق و طبیعی؛ تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"type":"writing","id":"c-x07-w2-w","course":"ielts-exams","exam":"exam-07","unit":"x07-w2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The benefits outweigh the costs.\" This means the benefits are...","options":["greater or more important than the costs","smaller than the costs","the same as the costs"],"correct":0,"why":{"en":"Outweigh = be greater in importance than.","tr":"Outweigh = önemce daha büyük olmak.","fa":"outweigh یعنی از نظر اهمیت بیشتر بودن."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase does NOT copy \"cheap air travel\" from the question?","options":["cheap air travel","air travel that is cheap","low-cost flights"],"correct":2,"why":{"en":"\"Low-cost flights\" says the same in other words.","tr":"\"Low-cost flights\" aynı şeyi başka kelimelerle söylüyor.","fa":"«low-cost flights» همان را با کلمه‌های دیگر می‌گوید."}},{"tests":"method","point":2,"prompt":"Where should you give your judgement in an advantages-and-disadvantages essay?","options":["only in the last sentence","in the introduction and again in the conclusion","nowhere: just list both sides"],"correct":1,"why":{"en":"State it early so the reader knows your view, and repeat it at the end.","tr":"Okur görüşünü bilsin diye erken belirt, sonunda tekrarla.","fa":"زود بگو تا خواننده نظرت را بداند و آخر کار تکرارش کن."}},{"tests":"trap","point":1,"prompt":"An essay describes three advantages and three disadvantages but never says which side is greater. What is missing?","options":["an answer to \"outweigh\"","more examples","a longer introduction"],"correct":0,"why":{"en":"The question asks which side is greater; without a judgement it is only half answered.","tr":"Soru hangi tarafın daha ağır bastığını soruyor; yargı olmadan yarım cevaplanmış olur.","fa":"سؤال می‌پرسد کدام طرف سنگین‌تر است؛ بدون داوری فقط نیمی از آن جواب داده شده."}}],"id":"c-x07-w2-x","course":"ielts-exams","exam":"exam-07","unit":"x07-w2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
